export const getACSInfo = (code) => {
  return acsData[code] || {
    area: (code.split(".")[1] || "?"),
    areaTitle: "Unknown Area",
    task: (code.split(".")[2] || "?"),
    taskTitle: "See FAA-S-ACS-6C",
    element: (code.split(".")[3] || "?"),
    elementType: "Knowledge",
    description: "ACS code not found — refer to FAA-S-ACS-6C",
    references: ["FAA-S-ACS-6C"],
    objective: "Refer to official ACS document"
  };
};

